content.content:
export type AniGorunumu = CheckIn & {
  mekanAdi: string
  /** Mekanin semti; bilinmiyorsa null. */
  mekanSemti: string | null
  mekanKonumu: { lat: number; lng: number }
  /** check_inler'de denormalize duran ad (karar #18). */
  kullaniciAdi: string | null
  /** Imzalanmis fotograf adresi; yoksa null. */
  fotografUrl: string | null
  etiketler: Etiket[]
}

type CheckInSatiriMekanli = CheckInSatiri & {
  mekanlar: { ad: string; konum: string; semt: string | null }
  kullanici_adi: string | null
}

export async function kullanicininAnilariniGetir(kullaniciId: string): Promise<AniGorunumu[]> {
  const { data, error } = await supabase
    .from('check_inler')
    .select(
      'id, mekan_id, kullanici_adi, not_metni, fotograf, olusturma_zamani, bitis_zamani, konum, bulunurluk, mekanlar(ad, konum, semt)'
    )
    .eq('kullanici_id', kullaniciId)
    // KONUM FILTRESI KALDIRILDI (kullanicinin bildirdigi eksik,
    // 2026-08-29): `.is('konum', null)` yalnizca ANILARI getiriyordu,
    // yani yeni yapilan bir check-in profil listesinde 30 dakika
    // boyunca HIC gorunmuyordu ve "Anı" sayaci da artmiyordu.
    // Artik canli check-in de listede; tunel onu "şu an burada"
    // rozetiyle ciziyor. Gorunurluk yine RLS'in isi.
    .order('olusturma_zamani', { ascending: false })
  if (error) throw new Error(hataMetni(error))
  const satirlar = data as unknown as CheckInSatiriMekanli[]

  // Etiketler TEK SORGUDA; okunamazsa anilar yine gosteriliyor.
  const etiketler: Record<string, Etiket[]> = await etiketleriGetir(
    satirlar.map((s) => s.id)
  ).catch(() => ({}))

  return Promise.all(
    satirlar.map(async (satir) => ({
      ...satiriCheckInACevir(satir),
      mekanAdi: satir.mekanlar.ad,
      // Semt zaman tunelindeki alt satirda kullaniliyor.
      mekanSemti: satir.mekanlar.semt,
      mekanKonumu: noktayiCoz(satir.mekanlar.konum),
      kullaniciAdi: satir.kullanici_adi,
      fotografUrl: satir.fotograf ? await checkInFotografiUrl(satir.fotograf) : null,
      etiketler: etiketler[satir.id] ?? [],
    }))
  )
}

/**
 * Bir check-in'i KALICI olarak siler.
 *
 * Ad 2026-08-26'da `aniyiSil`den degistirildi: ayni satir hem CANLI
 * check-in hem de ani olabiliyor ve kullanici ikisini de silebilmeli
 * (kullanicinin istegi). Silme politikasi zaten `kullanici_id =
 * auth.uid()`, yani durum ayrimi yapmiyor.
=== INDEX handlers
   * ve kullanici yazdigi metni kaybetmiyor.
   */
  async function notuKaydet(id: string, yeniNot: string) {
    await checkInNotunuGuncelle(id, yeniNot)
    const temiz = yeniNot.trim()
    setOgeler((mevcut) =>
      mevcut.map((o) => (o.id === id ? { ...o, notMetni: temiz === '' ? null : temiz } : o))
    )
  }

  async function ifadeyiKaydet(id: string, ifade: string | null) {
    await checkInIfadesiniGuncelle(id, ifade)
    setOgeler((mevcut) => mevcut.map((o) => (o.id === id ? { ...o, ifade } : o)))
  }

  async function etiketEkle(id: string, kullaniciIdler: string[]) {
    await etiketleriKaydet(id, kullaniciIdler)
    // KAYDEDINCE HEMEN GORUNSUN (kullanicinin istegi 2026-09-18): sunucu
    // karsi tarafin ayarina gore etiketi ya hemen onayliyor ya onaya
    // dusuruyor; hangisi oldugunu tahmin etmek yerine o check-in'in
    // onayli etiketleri yeniden okunup karta yaziliyor. Onaya dusen
    // etiket onaylanana kadar gorunmez (eski kural).
    const guncel = await etiketleriGetir([id]).catch(() => null)
    if (guncel) {
      setOgeler((mevcut) => mevcut.map((o) => (o.id === id ? { ...o, etiketler: guncel[id] ?? [] } : o)))
    }
  }

  async function etiketiSil(id: string, kullaniciId: string) {
    await etiketiKaldir(id, kullaniciId)
    setOgeler((mevcut) =>
      mevcut.map((o) =>
        o.id === id
          ? { ...o, etiketler: o.etiketler.filter((e) => e.kullaniciId !== kullaniciId) }
          : o
      )
    )
  }

  // Ref'i state ile ayni tutuyoruz; okuyanlar (tazeleme, sonraki
  // sayfa) her zaman guncel listeyi gorsun.
=== PROFIL handlers

  // Hata pencereye birakiliyor (akis ekranindaki desen): kayit
  // basarisizsa pencere acik kalsin, yazilan metin kaybolmasin.
  async function notuKaydet(checkInId: string, yeniNot: string) {
    await checkInNotunuGuncelle(checkInId, yeniNot)
    const temiz = yeniNot.trim()
    setAnilar((mevcut) =>
      mevcut.map((a) => (a.id === checkInId ? { ...a, notMetni: temiz === '' ? null : temiz } : a))
    )
  }

  async function ifadeyiKaydet(checkInId: string, ifade: string | null) {
    await checkInIfadesiniGuncelle(checkInId, ifade)
    setAnilar((mevcut) => mevcut.map((a) => (a.id === checkInId ? { ...a, ifade } : a)))
  }

  // Ana sayfadaki etiketEkle ile ayni: kaydet, onayli etiketleri yeniden
  // oku, karta yaz (kullanicinin istegi 2026-09-18: hemen gorunsun).
  async function etiketEkle(checkInId: string, kullaniciIdler: string[]) {
    await etiketleriKaydet(checkInId, kullaniciIdler)
    const guncel = await etiketleriGetir([checkInId]).catch(() => null)
    if (guncel) {
      setAnilar((mevcut) =>
        mevcut.map((a) => (a.id === checkInId ? { ...a, etiketler: guncel[checkInId] ?? [] } : a))
      )
    }
  }

  async function etiketiSil(checkInId: string, kisiId: string) {
    await etiketiKaldir(checkInId, kisiId)
    setAnilar((mevcut) =>
      mevcut.map((a) =>
        a.id === checkInId
          ? { ...a, etiketler: (a.etiketler ?? []).filter((e) => e.kullaniciId !== kisiId) }
          : a
      )
    )
  }

  // Ekran her odaklandiginda yeniden cekiliyor: kullanici check-in yapip
  // ya da bir aniyi silip buraya donunce sayilar ve canli serit eski

