  it('yukleme yarida kirilirsa o ana kadar yuklenenler geri silinir, RPC hic cagrilmaz', async () => {
    ;(checkinFotograflariniYukle as jest.Mock).mockImplementation(async (_uid: string, _uriler: string[], kismi?: string[]) => {
