      <Pressable style={stiller.zemin} testID="ifade-zemini" onPress={onKapat}>
        <Animated.View
          style={[stiller.sayfa, { paddingBottom: Math.max(guvenliAlan.bottom, bosluk.s) + bosluk.s, transform: [{ translateY: girisY }] }]}
        >
