import io, re

def oku(p): return io.open(p, encoding='utf-8').read()
def yaz(p, s): io.open(p, 'w', encoding='utf-8', newline='\n').write(s)
class R:
    def __init__(self, p): self.p = p; self.s = oku(p)
    def rep(self, old, new, n=1):
        assert self.s.count(old) == n, (self.p, old[:80], self.s.count(old)); self.s = self.s.replace(old, new)
    def kes(self, bas, son, son_dahil=False):
        a = self.s.index(bas); b = self.s.index(son, a) + (len(son) if son_dahil else 0)
        self.s = self.s[:a] + self.s[b:]
    def yaz(self): yaz(self.p, self.s)

# ---------------- lib/akis.ts: fotograf birimleri
f = R('lib/akis.ts')
f.s = f.s.rstrip('\n') + """

/**
 * Galeriler icin FOTOGRAF BIRIMI (coklu fotograf, 2026-09-21): profil
 * izgarasi, baskasinin profili ve gezgin "ani" degil "fotograf" sayar.
 * Iki fotografli bir ani iki birimdir; sira: anilar sirasi, ani icinde
 * fotograf sirasi.
 */
export type FotografBirimi<T> = { id: string; ani: T; indeks: number; url: string }

export function fotografBirimleri<T extends { id: string; fotografUrller: string[] }>(
  anilar: T[]
): FotografBirimi<T>[] {
  return anilar.flatMap((ani) =>
    ani.fotografUrller.map((url, indeks) => ({ id: `${ani.id}-${indeks}`, ani, indeks, url }))
  )
}
"""
f.yaz()

